import os
from pathlib import Path
# Local env parsing is deliberately limited to simple key=value configuration generated by setup.
configuration = Path(__file__).with_name(".env.local")
if configuration.exists():
    for line in configuration.read_text(encoding="utf-8-sig").splitlines():
        if line.strip() and not line.lstrip().startswith("#"):
            name, separator, value = line.partition("=")
            if not separator or not name.strip().replace("_", "").isalnum():
                raise RuntimeError("Invalid local AI configuration")
            os.environ.setdefault(name.strip(), value.strip())
os.environ.setdefault("HF_HUB_DISABLE_SYMLINKS_WARNING", "1")
os.environ.setdefault("HF_HUB_DISABLE_XET", "1")
import os
from pathlib import Path

env_path = Path(__file__).parent / ".env"
if env_path.exists():
    for line in env_path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if line and not line.startswith("#") and "=" in line:
            k, v = line.split("=", 1)
            os.environ.setdefault(k.strip(), v.strip().strip('"').strip("'"))
import uvicorn
from app.main import create_app
if __name__ == "__main__":
    uvicorn.run(create_app(), host="127.0.0.1", port=8000, access_log=False)

